/**
 * Real-model online E2E: auth → booking app generated by qwen → second-turn edit.
 * Asserts the real model was used (not the fallback) and that both turns end done.
 *
 * Usage: BASE_URL=https://... node scripts/verify-real-agent-online.mjs
 */
import { chromium } from "@playwright/test";

const BASE = process.env.BASE_URL || "https://vibeforge-interview-demo.netlify.app";
const results = [];
const check = (name, ok, detail = "") => {
  results.push(ok);
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? ` — ${detail}` : ""}`);
};

const browser = await chromium.launch({ channel: "msedge", headless: true });
const context = await browser.newContext({ viewport: { width: 1512, height: 950 } });
const page = await context.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(`pageerror: ${e.message}`));
page.on("console", (m) => {
  if (m.type() === "error") errors.push(`console.error: ${m.text().slice(0, 160)}`);
});

const waitBuilds = (n, timeout = 720000) =>
  page.waitForFunction(
    (expected) => document.body.textContent.split("已构建").length - 1 >= expected,
    n,
    { timeout },
  );

const chatText = () => page.getByTestId("chat-messages").innerText();

await page.goto(BASE, { waitUntil: "networkidle", timeout: 120000 });
await page.waitForTimeout(1200);
await page.getByRole("button", { name: /使用演示账号一键体验/ }).click();
await page.waitForTimeout(1800);
await page.getByRole("button", { name: /新建应用/ }).click();
await page.waitForTimeout(500);

const t0 = Date.now();
await page.locator("textarea").first().fill(
  "做一个会议室预约系统：可以按时间段预约会议室，同一会议室时间冲突时要提示",
);
await page.keyboard.press("Enter");
try {
  await waitBuilds(1);
} catch (err) {
  console.log("TIMEOUT dump:", (await page.locator("body").innerText()).slice(0, 1200).replace(/\n+/g, " | "));
  await page.screenshot({ path: "shots/real-agent-timeout.png" });
  throw err;
}
const t1 = Date.now();
const first = await chatText();
const firstAll = await page.locator("body").innerText();
check("real model used (latency > 20s, mock is ~6s)", t1 - t0 > 20000, `${((t1 - t0) / 1000).toFixed(1)}s`);
check(
  "no fallback to built-in generator",
  !/暂不可用|已切换为内置生成器/.test(firstAll + first),
);
check("first generation done", /已构建/.test(first), `${((t1 - t0) / 1000).toFixed(1)}s`);

const planText = await page.locator("main section").first().innerText();
check("booking plan", /会议室|预约/.test(planText), planText.split("\n").find((l) => l.trim()) ?? "");

await page.waitForTimeout(1500);
const frameBody = page.frameLocator("iframe[title='应用预览']").locator("body");
const appText = (await frameBody.innerText()).replace(/\s+/g, " ");
check("app shows booking domain (rooms / time)", /会议室|云杉厅|开始|结束|预约/.test(appText), appText.slice(0, 70));

await page.getByRole("button", { name: /^代码/ }).first().click();
await page.waitForTimeout(700);
await page.getByRole("button", { name: /app\.js/ }).click();
await page.waitForTimeout(500);
const code = await page.locator(".code-pre").innerText();
check(
  "generated code has overlap/conflict validation",
  /冲突|重叠|overlap|conflict|isConflict|checkConflict/i.test(code),
  `${(code.length / 1024).toFixed(1)}KB`,
);
check(
  "app was generated by the model (not the built-in booking recipe)",
  !/vf:booking:v1|云杉厅|白桦厅/.test(code),
);
await page.getByRole("button", { name: /^预览/ }).first().click();
await page.waitForTimeout(400);

const t2 = Date.now();
const composer = page.getByPlaceholder(/继续描述你的修改|Agent 正在构建/);
await composer.fill("把标题改成「会议室预订系统」，并确认预约时间冲突时会被拦截");
await composer.press("Enter");
await waitBuilds(2);
const t3 = Date.now();
const second = await chatText();
check("second turn done with real model", /已构建/.test(second), `${((t3 - t2) / 1000).toFixed(1)}s`);
const renamedPlan = await page.locator("main section").first().innerText();
check("rename applied", /会议室预订系统/.test(renamedPlan), renamedPlan.split("\n").find((l) => l.trim()) ?? "");
const appText2 = (await frameBody.innerText()).replace(/\s+/g, " ");
check("app still booking-correct after edit", /会议室|预约/.test(appText2), appText2.slice(0, 70));

await page.screenshot({ path: "shots/real-agent-booking.png", fullPage: false });
console.log("console/page errors:", errors.length ? errors.slice(0, 8) : "none");
const failed = results.filter((ok) => !ok).length;
console.log(failed ? `\n${failed} check(s) failed` : "\nall real-agent checks passed");
await browser.close();
process.exitCode = failed || errors.length ? 1 : 0;
